// Involute gears (README §4.9 j.lib.gear): spur, helical, herringbone, internal and rack.
// Teeth are generated by the ISO 53 basic rack (α, addendum m, dedendum 1.25 m, tip radius 0.38 m) rolling on
// the pitch circle: exact involute flanks, the trochoidal root fillet, and undercut on small pinions. Profile
// shift x moves the rack by x·m. Backlash thins each tooth on the pitch circle: a fit class c gives c / cos α
// per gear (so a printed pair has 2c between the idle flanks, like a pin in a hole); it is resolved when the
// part compiles, from the fit context in force. Gears are parts with ports 'axis' and 'pitch'; their spec is
// kept in part.meta.sets.gear for j.inspect.gearMesh.
import { part } from './part.js';
import { Region } from './region.js';
import { fit as fitApi, DEFAULT_CLASSES } from './fit.js';

const inv = a => Math.tan(a) - a;
const num = x => x == null ? null : typeof x === 'number' ? x : x.value ?? Number(x);
const angleOf = x => x == null ? null : typeof x === 'number' ? x * Math.PI / 180 : x.value;

// Polar samples of the upper flank (θ > 0) of the tooth centred on angle 0.
// → { rp, rb, ra, rf, fillet: [[r, θ]…] root → form (or undercut crossing), involute: [[r, θ]…] → tip,
//     rootAngle, formRadius, undercut }
export function toothFlank({ m, z, alpha, x = 0, ds = 0, ha = 1, hf = 1.25, rho = 0.38, generated = true, samples = 10, filletSamples = 14 }) {
  const rp = m * z / 2, rb = rp * Math.cos(alpha), p = Math.PI * m, ta = Math.tan(alpha);
  const rf = rp - m * (hf - x), ra0 = rp + m * (ha + x);
  const sp = p / 2 - ds + 2 * x * m * ta;                 // tooth thickness on the pitch circle
  const psi = sp / (2 * rp) + inv(alpha);
  const thInv = r => r < rb ? Infinity : psi - inv(Math.acos(Math.min(1, rb / r)));
  // generating rack: datum line at D from the centre; the flank facing the tooth: u = u0 + v·tan α
  const D = rp + x * m, u0 = p / 4 - ds / 2;
  const rhoMax = Math.max(0, (p / 2 - u0 - hf * m * ta) * Math.cos(alpha) / (1 - Math.sin(alpha)));
  const rr = generated ? Math.min(rho * m, 0.95 * rhoMax) : 0;
  const vc = hf * m - rr, uc = u0 + vc * ta + rr / Math.cos(alpha);
  // envelope of the rack tip circle: the contact point lies on the line through the pitch point (rp, 0)
  const env = phi => {
    const Cx = D - vc, Cy = uc + rp * phi;
    let ex = Cx - rp, ey = Cy; const L = Math.hypot(ex, ey) || 1; ex /= L; ey /= L;
    const Px = Cx + rr * ex, Py = Cy + rr * ey, c = Math.cos(phi), s = Math.sin(phi);
    const gx = Px * c + Py * s, gy = -Px * s + Py * c;
    return [Math.hypot(gx, gy), Math.atan2(gy, gx)];
  };
  const phiA = -uc / rp, phiB = ((D - vc - rp) / ta - uc) / rp;   // root point · form point (flank tangency)
  const undercut = generated && (vc + rr * Math.sin(alpha) - x * m) > rp * Math.sin(alpha) ** 2 + 1e-12;
  let fillet = [], rStart;
  if (generated) {
    const N = filletSamples;
    for (let k = 0; k <= N; k++) fillet.push(env(phiA + (phiB - phiA) * k / N));
    if (undercut) {
      // the tip trochoid cuts into the involute: keep it up to where it crosses the involute
      const f = phi => { const [r, t] = env(phi); return thInv(r) - t; };
      let k = fillet.findIndex(([r, t]) => r >= rb && t >= thInv(r));
      if (k > 0) {
        let lo = phiA + (phiB - phiA) * (k - 1) / N, hi = phiA + (phiB - phiA) * k / N;
        for (let i = 0; i < 60; i++) { const mid = (lo + hi) / 2; if (f(mid) > 0) lo = mid; else hi = mid; }
        fillet = [...fillet.slice(0, k), env((lo + hi) / 2)];
      }
    }
    rStart = Math.max(rb, fillet[fillet.length - 1][0]);
    fillet[fillet.length - 1] = [rStart, thInv(rStart)];   // join exactly on the involute
  } else rStart = Math.max(rb, rf);
  // tip: cut a pointed tooth where the land would be under 0.05 m
  let ra = ra0;
  if (thInv(ra) * ra < 0.025 * m) { let lo = rStart, hi = ra0; for (let i = 0; i < 50; i++) { const mid = (lo + hi) / 2; if (thInv(mid) * mid > 0.025 * m) lo = mid; else hi = mid; } ra = lo; }
  const e0 = Math.sqrt(Math.max(0, (rStart / rb) ** 2 - 1)), e1 = Math.sqrt(Math.max(0, (ra / rb) ** 2 - 1));
  const involute = Array.from({ length: samples }, (_, k) => { const e = e0 + (e1 - e0) * k / (samples - 1); const r = rb * Math.sqrt(1 + e * e); return [r, thInv(r)]; });
  return { rp, rb, ra, rf, fillet: dedupe(fillet), involute: dedupe(involute), rootAngle: generated ? uc / rp : thInv(rStart), formRadius: rStart, undercut, rho: rr };
}
const dedupe = pts => pts.filter((q, i) => !i || Math.hypot(q[0] - pts[i - 1][0], q[1] - pts[i - 1][1]) > 1e-7);

// Closed outline of an external gear (one loop) from the tooth flank; ids `${id}.t<i>.<role>`.
export function gearLoop(o) {
  const T = toothFlank(o), z = o.z, id = o.id ?? 'gear';
  const step = 2 * Math.PI / z, P = (r, a) => [r * Math.cos(a), r * Math.sin(a)];
  const segs = [];
  const thTip = T.involute[T.involute.length - 1][1];
  for (let i = 0; i < z; i++) {
    const c = i * step, t = `${id}.t${i + 1}`;
    const lower = (pts, sgn) => pts.map(([r, th]) => P(r, c + sgn * th));
    if (o.generated !== false && T.fillet.length > 1) segs.push({ kind: 'spline', pts: lower(T.fillet, -1), src: `${t}.filletR` });
    else if (T.rf < T.formRadius - 1e-9) segs.push({ kind: 'line', a: P(T.rf, c - T.rootAngle), b: P(T.formRadius, c - T.rootAngle), src: `${t}.rootR` });
    segs.push({ kind: 'spline', pts: lower(T.involute, -1), src: `${t}.flankR` });
    segs.push({ kind: 'arc', c: [0, 0], r: T.ra, a0: c - thTip, a1: c + thTip, ccw: true, src: `${t}.tip` });
    segs.push({ kind: 'spline', pts: lower(T.involute.slice().reverse(), 1), src: `${t}.flankL` });
    if (o.generated !== false && T.fillet.length > 1) segs.push({ kind: 'spline', pts: lower(T.fillet.slice().reverse(), 1), src: `${t}.filletL` });
    else if (T.rf < T.formRadius - 1e-9) segs.push({ kind: 'line', a: P(T.formRadius, c + T.rootAngle), b: P(T.rf, c + T.rootAngle), src: `${t}.rootL` });
    const a0 = c + T.rootAngle, a1 = c + step - T.rootAngle;
    if (a1 - a0 > 1e-9) segs.push({ kind: 'arc', c: [0, 0], r: T.rf, a0, a1, ccw: true, src: `${t}.root` });
  }
  return { loop: segs, ...T };
}
// kept for callers of the first version
export const involuteLoop = ({ m, z, alpha, shift = 0, backlash = 0, addendum = 1, dedendum = 1.25, id = 'gear', samples = 9 }) =>
  gearLoop({ m, z, alpha, x: shift, ds: backlash, ha: addendum, hf: dedendum, id, samples, generated: false });

// Backlash: a fit class name ('fit' = 'slide') resolves in the compile's fit context; a length is used as is.
function backlashSpec(b) {
  if (b == null || b === 'fit') return fitApi.gap('slide');
  if (typeof b === 'string') { if (!(b in DEFAULT_CLASSES)) throw new Error(`gear backlash: unknown fit class '${b}'`); return fitApi.gap(b); }
  return b;
}
function thinning(spec, len, alpha) {
  const b = spec.backlash;
  if (b?.isFitValue) { const c = num(len(b)); return (Number.isFinite(c) ? c : DEFAULT_CLASSES[/gap\((\w+)\)/.exec(b.text)?.[1]] ?? 0.2) / Math.cos(alpha); }
  const v = num(len(b)); return Number.isFinite(v) ? v : 0;
}
const circleLoop = (r, src) => [{ kind: 'circle', c: [0, 0], r, src }];
// Gear outlines as regions computed at compile time (so backlash follows the fit context).
function lowerGear(s, len) {
  const ds = thinning(s, len, s.alpha);
  if (s.kind === 'rack') return [{ loops: [rackLoop(s, ds)] }];
  if (s.kind === 'internal') {
    // ring = rim minus a cutter whose teeth are the ring's tooth spaces (thicker by the backlash); the ring's
    // tips stop at the base circle so they stay involute
    const rp = s.m * s.z / 2, rb = rp * Math.cos(s.alpha);
    const hf = Math.min(1, (rp - rb) / s.m - s.x - 1e-6);
    const C = gearLoop({ m: s.m, z: s.z, alpha: s.alpha, x: -s.x, ds: -ds, ha: 1.25, hf, id: 'ring', generated: false });
    return [{ loops: [circleLoop(C.ra + s.rim, 'rim'), C.loop] }];
  }
  const G = gearLoop({ m: s.m, z: s.z, alpha: s.alpha, x: s.x, ds, id: 'gear' });
  return [{ loops: [G.loop, ...(s.bore ? [circleLoop(s.bore / 2, 'bore')] : [])] }];
}
function rackLoop(s, ds) {
  const { m, alpha } = s, count = s.teeth, p = Math.PI * m, base = s.base, ta = Math.tan(alpha);
  const ha = m, hf = 1.25 * m;
  const half = v => (p / 2 - ds) / 2 - v * ta;          // tooth half-thickness at height v above the pitch line
  const pts = [[0, -hf - base]];
  for (let i = 0; i < count; i++) {
    const c = i * p + p / 2;
    pts.push([i * p, -hf], [c - half(-hf), -hf], [c - half(ha), ha], [c + half(ha), ha], [c + half(-hf), -hf]);
  }
  pts.push([count * p, -hf], [count * p, -hf - base]);
  return pts.map((a, i) => ({ kind: 'line', a, b: pts[(i + 1) % pts.length], src: `rack.${i + 1}` })).filter(sg => Math.hypot(sg.a[0] - sg.b[0], sg.a[1] - sg.b[1]) > 1e-9);
}
const gearRegion = spec => new Region({ op: 'custom', kind: 'gear', ...spec, lower: lowerGear });

function common(o) {
  const m = num(o.module ?? 1), z = o.teeth ?? 20, alpha = angleOf(o.pressure ?? 20), width = num(o.width ?? 5);
  if (!(m > 0)) throw new Error('gear: module must be positive');
  if (!(Number.isInteger(z) && z >= 3)) throw new Error(`gear: teeth must be a whole number ≥ 3 (got ${z})`);
  return { m, z, alpha, width, x: o.shift ?? 0, backlash: backlashSpec(o.backlash), bore: o.bore != null ? num(o.bore) : null };
}
function info(kind, g, extra = {}) {
  const rp = g.m * g.z / 2;
  const T = kind === 'rack' ? null : toothFlank({ m: g.m, z: g.z, alpha: g.alpha, x: kind === 'internal' ? 0 : g.x });
  return { kind, module: g.m, teeth: g.z, pressure: g.alpha, shift: g.x, backlash: g.backlash?.isFitValue ? /gap\((\w+)\)/.exec(g.backlash.text)?.[1] ?? 'slide' : num(g.backlash), width: g.width,
    pitchRadius: rp, baseRadius: rp * Math.cos(g.alpha), tipRadius: T?.ra, rootRadius: T?.rf, undercut: T?.undercut ?? false, ...extra };
}
function withPorts(p, rp) {
  return p.port('axis', { origin: [0, 0, 0], x: [1, 0, 0], z: [0, 0, 1] }).port('pitch', { origin: [rp, 0, 0], x: [0, 1, 0], z: [0, 0, 1] });
}

export function spur(o = {}) {
  const g = common(o);
  const spec = info('spur', g);
  return withPorts(part(o.name ?? `gear-z${g.z}`).params({ module: g.m, teeth: g.z }).set('gear', spec)
    .extrude(gearRegion({ kind: 'spur', m: g.m, z: g.z, alpha: g.alpha, x: g.x, backlash: g.backlash, bore: g.bore }), g.width, { id: 'gear' }), spec.pitchRadius);
}
// Helical (one hand) and herringbone (a V of two helices): twisted extrudes of the transverse profile, so the
// module is the transverse module (pitch diameter m·z, as for a spur). Twist over a height h: h·tan β / r_p.
function twisted(kind, o, herring) {
  const g = common(o);
  const beta = angleOf(o.helix ?? 30), hand = o.hand ?? 'right';
  if (!(Math.abs(beta) < Math.PI / 2 * 0.9)) throw new Error('gear: helix angle must be under 80°');
  const rp = g.m * g.z / 2, h = herring ? g.width / 2 : g.width;
  const twist = h * Math.tan(beta) / rp * (hand === 'left' ? -1 : 1);
  const spec = info(kind, g, { helix: beta, hand, twist });
  return withPorts(part(o.name ?? `${kind}-z${g.z}`).params({ module: g.m, teeth: g.z }).set('gear', spec)
    .extrude(gearRegion({ kind: 'spur', m: g.m, z: g.z, alpha: g.alpha, x: g.x, backlash: g.backlash, bore: g.bore }), g.width, { id: 'gear', twist, herringbone: herring }), rp);
}
export const helical = (o = {}) => twisted('helical', o, false);
export const herringbone = (o = {}) => twisted('herringbone', o, true);
// Internal (ring) gear: { rim } outside the root circle; { herringbone, helix, hand } twists it like the pinion.
export function internal(o = {}) {
  const g = common(o);
  const rim = num(o.rim ?? 3), rp = g.m * g.z / 2;
  const twist = o.herringbone || o.helix ? (o.herringbone ? g.width / 2 : g.width) * Math.tan(angleOf(o.helix ?? 30)) / rp * (o.hand === 'left' ? -1 : 1) : 0;
  const spec = info('internal', g, { internal: true, rim, herringbone: !!o.herringbone, helix: twist ? angleOf(o.helix ?? 30) : 0, hand: o.hand ?? 'right', outerRadius: rp + 1.25 * g.m - g.x * g.m + rim });
  const reg = gearRegion({ kind: 'internal', m: g.m, z: g.z, alpha: g.alpha, x: g.x, backlash: g.backlash, rim });
  return withPorts(part(o.name ?? `ring-z${g.z}`).params({ module: g.m, teeth: g.z }).set('gear', spec)
    .extrude(reg, g.width, twist ? { id: 'gear', twist, herringbone: !!o.herringbone } : { id: 'gear' }), rp);
}
// Rack: straight flanks at the pressure angle along +X, pitch line at y = 0, `base` below the roots.
export function rack(o = {}) {
  const g = common({ ...o, teeth: Math.max(3, o.teeth ?? 10) });
  const count = o.teeth ?? 10, base = num(o.base ?? 2 * g.m);
  const spec = { kind: 'rack', module: g.m, teeth: count, pressure: g.alpha, width: g.width, pitch: Math.PI * g.m, length: count * Math.PI * g.m, backlash: info('rack', g).backlash };
  return part(o.name ?? `rack-m${g.m}`).set('gear', spec).extrude(gearRegion({ kind: 'rack', m: g.m, teeth: count, alpha: g.alpha, backlash: g.backlash, base }), g.width, { id: 'rack' })
    .port('pitch', { origin: [0, 0, 0], x: [1, 0, 0], z: [0, 0, 1] });
}
export const gear = { spur, helical, herringbone, internal, rack, bevel: () => { throw new Error('j.lib.gear.bevel is not supported yet'); } };

// ── meshing check (j.inspect.gearMesh) ────────────────────────────────────────
export const gearSpecOf = g => g?.meta?.sets?.gear ?? g?.spec ?? g;
// Working pressure angle from inv αw = inv α + 2 tan α (x₂ ± x₁)/(z₂ ± z₁) (Newton on inv).
function workingAngle(alpha, x, zs) { const target = inv(alpha) + 2 * Math.tan(alpha) * x / zs; let a = alpha; for (let i = 0; i < 40; i++) a -= (inv(a) - target) / (Math.tan(a) ** 2); return a; }
export function meshReport(a, b, o = {}, ctx = {}) {
  const A = gearSpecOf(a), B = gearSpecOf(b);
  const msgs = [];
  const m = A.module, alpha = A.pressure;
  if (Math.abs(A.module - B.module) > 1e-9) msgs.push(`modules differ: ${A.module} vs ${B.module} mm`);
  if (Math.abs(A.pressure - B.pressure) > 1e-9) msgs.push(`pressure angles differ: ${(A.pressure * 180 / Math.PI).toFixed(1)}° vs ${(B.pressure * 180 / Math.PI).toFixed(1)}°`);
  const gapOf = s => s.backlash == null ? 0 : typeof s.backlash === 'string' ? (ctx.classes?.[s.backlash] ?? DEFAULT_CLASSES[s.backlash] ?? 0.2) / Math.cos(s.pressure) : num(s.backlash);
  const backlash = (gapOf(A) + gapOf(B)) * Math.cos(alpha);   // normal backlash at the standard centre distance
  if (A.kind === 'rack' || B.kind === 'rack') {
    const G = A.kind === 'rack' ? B : A;
    const d = G.pitchRadius + (G.shift ?? 0) * m;
    return { ok: !msgs.length, module: m, pressure: alpha, centreDistance: d, pitchLineDistance: d, travelPerTurn: Math.PI * m * G.teeth, backlash, messages: msgs };
  }
  const ring = A.internal ? A : B.internal ? B : null, pin = ring === A ? B : A;
  const twistedA = ['helical', 'herringbone'].includes(A.kind) || A.helix, twistedB = ['helical', 'herringbone'].includes(B.kind) || B.helix;
  if (!!twistedA !== !!twistedB) msgs.push('one gear is helical and the other is not');
  else if (twistedA) {
    if (Math.abs(A.helix - B.helix) > 1e-9) msgs.push('helix angles differ');
    const sameHand = (A.hand ?? 'right') === (B.hand ?? 'right');
    if (ring ? !sameHand : sameHand) msgs.push(ring ? 'an internal helical pair needs the same hand' : `an external helical pair needs opposite hands (both are ${A.hand ?? 'right'})`);
  }
  let zs, xs, sign;
  if (ring) { zs = ring.teeth - pin.teeth; xs = (ring.shift ?? 0) - (pin.shift ?? 0); sign = -1; if (zs < 10) msgs.push(`ring has ${ring.teeth} teeth and pinion ${pin.teeth}: under 10 apart, the tips foul`); }
  else { zs = A.teeth + B.teeth; xs = (A.shift ?? 0) + (B.shift ?? 0); sign = 1; }
  const aw = workingAngle(alpha, xs, zs);
  const standard = m * zs / 2, centre = standard * Math.cos(alpha) / Math.cos(aw);
  // contact ratio along the line of action
  const rb1 = pin.baseRadius ?? pin.pitchRadius * Math.cos(alpha), ra1 = pin.tipRadius ?? pin.pitchRadius + m;
  let eps;
  if (ring) { const rb2 = ring.baseRadius, ra2 = Math.max(ring.pitchRadius - m * (1 + (ring.shift ?? 0)), rb2); eps = (Math.sqrt(ra1 * ra1 - rb1 * rb1) - Math.sqrt(Math.max(0, ra2 * ra2 - rb2 * rb2)) + centre * Math.sin(aw)) / (Math.PI * m * Math.cos(alpha)); }
  else { const G2 = pin === A ? B : A; const rb2 = G2.baseRadius ?? G2.pitchRadius * Math.cos(alpha), ra2 = G2.tipRadius ?? G2.pitchRadius + m; eps = (Math.sqrt(ra1 * ra1 - rb1 * rb1) + Math.sqrt(ra2 * ra2 - rb2 * rb2) - centre * Math.sin(aw)) / (Math.PI * m * Math.cos(alpha)); }
  if (eps < 1.1) msgs.push(`contact ratio ${eps.toFixed(2)} < 1.1: the teeth lose contact`);
  for (const G of [A, B]) if (G.undercut) msgs.push(`${G.teeth} teeth (shift ${G.shift ?? 0}) are undercut; shift: ${Math.max(0, 1 - G.teeth * Math.sin(G.pressure) ** 2 / 2).toFixed(2)} avoids it`);
  if (o.centreDistance != null) { const d = num(o.centreDistance); if (Math.abs(d - centre) > (o.tolerance != null ? num(o.tolerance) : 0.01)) msgs.push(`centre distance ${d.toFixed(3)} mm ≠ ${centre.toFixed(3)} mm`); }
  const errs = msgs.filter(s => !/undercut/.test(s));
  return { ok: !errs.length, module: m, pressure: alpha, workingPressure: aw, centreDistance: centre, standardCentreDistance: standard, contactRatio: eps,
    ratio: ring ? ring.teeth / pin.teeth : B.teeth / A.teeth, backlash, messages: msgs, internal: !!ring, sign };
}
